def _get_assertion_iterator(iterable):
    # Generator expressions acquire their outer iterator immediately.  The
    # adapter also avoids calling a user iterator's __iter__ a second time.
    iterator = iter(iterable)

    def consume():
        while True:
            try:
                value = next(iterator)
            except StopIteration:
                return
            yield value

    return consume()


